function cell(text,w,opts={}){
  const paras=(Array.isArray(text)?text:[text]).map(t=>new Paragraph({children:[new TextRun({text:t,bold:!!opts.bold,italics:!!opts.italic,color:opts.color,font:opts.mono?"Consolas":undefined,size:opts.mono?18:20})]}));
  return new TableCell({width:{size:w,type:WidthType.DXA},borders,margins:{top:80,bottom:80,left:120,right:120},
    shading:opts.fill?{type:ShadingType.CLEAR,color:"auto",fill:opts.fill}:undefined,children:paras});
}
function bug(n,title,rows){
  const out=[new Paragraph({heading:HeadingLevel.HEADING_2,spacing:{before:300,after:120},children:[new TextRun(`#${n}  ${title}`)]})];
  out.push(new Table({width:{size:W,type:WidthType.DXA},columnWidths:[L,R],rows:rows.map(([k,v,o])=>new TableRow({children:[cell(k,L,{bold:true,fill:"F2E6E8"}),cell(v,R,o||{})]}))}));
  return out;
}
